#!/usr/bin/env python3
"""news-image-20261118 entry: write the front-page image to /output/entry.png.

The image is a 1024x1024 newspaper front page summing up Wednesday
18 November 2026: the Gulf tanker crisis, the Kerch Bridge strikes,
Gaza's floods and cold, COP31's final days, Quad talks in Manila and
North Korea's missile launch. It is stored zlib-compressed and base64
encoded below (standard library only), so the program needs no network
and no files beside itself, and both graded runs write byte-identical
output.

The front page itself was composed with PIL: four original flat
editorial illustrations for the Gulf, the bridge, Gaza and COP31, two
small panels drawn with PIL shapes, and all text rendered by PIL.
"""

import base64
import os
import zlib

DATA = ""

def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    with open(os.path.join(out_dir, "entry.png"), "wb") as fh:
        fh.write(zlib.decompress(base64.b64decode(DATA)))

if __name__ == "__main__":
    main()
